<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{api}from'../api';const rows=ref<any[]>([]),show=ref(false),form=reactive({name:'',short_name:'',contact:'',timezone:'Asia/Shanghai',plan_code:'trial',device_limit:3,member_limit:3,subscription_days:30,owner_username:'',owner_password:'',owner_name:''});async function load(){rows.value=(await api('/tk-api/enterprise/platform/tenants')).tenants;}async function save(){await api('/tk-api/enterprise/platform/tenants',{method:'POST',body:JSON.stringify(form)});show.value=false;load();}onMounted(load);</script>
<template><section class="panel"><header class="panel-head"><div><span class="eyebrow">TENANT BUSINESS</span><h2>企业客户与订阅</h2><p>统一开通企业、设备额度、订阅周期和首位主管账号。</p></div><button class="primary" @click="show=!show">开通企业</button></header><form v-if="show" class="tenant-form" @submit.prevent="save"><input v-model="form.name" placeholder="企业全称" required><input v-model="form.short_name" placeholder="企业简称"><input v-model="form.contact" placeholder="联系人"><select v-model="form.plan_code"><option value="trial">试用版</option><option value="basic">基础版</option><option value="pro">专业版</option><option value="custom">定制版</option></select><input v-model.number="form.device_limit" type="number" placeholder="设备额度"><input v-model.number="form.subscription_days" type="number" placeholder="订阅天数"><input v-model="form.owner_username" placeholder="主管登录账号" required><input v-model="form.owner_password" type="password" placeholder="主管初始密码" required><button class="primary">确认开通</button></form><div class="tenant-grid"><article v-for="x in rows"><header><span class="tenant-logo">{{x.name.slice(0,1)}}</span><div><b>{{x.name}}</b><small>{{x.tenant_code}}</small></div><span class="plan">{{x.plan_code}}</span></header><div class="usage"><span>设备使用</span><strong>{{x.devices_used}} / {{x.device_limit}}</strong><i><em :style="{width:`${Math.min(100,x.devices_used/x.device_limit*100)}%`}"></em></i></div><footer><span>{{x.contact||'未设置联系人'}}</span><span>到期 {{x.subscription_expires_at?.slice(0,10)||'-'}}</span></footer></article></div></section></template>
